import { FormBuilder, FormGroup } from '@angular/forms';

import { IAuthUser } from '../interfaces/IAuthUser';

export class AuthUser implements IAuthUser {
    id: string;
    firstname: string;
    lastname: string;
    username: string;
    password: string;

    constructor() {
        this.id = '';
        this.firstname = '';
        this.lastname = '';
        this.username = '';
        this.password = '';
    }

    createForm(fb: FormBuilder): FormGroup {
        return fb.group({
            firstname: [this.firstname || ''],
            lastname: [this.lastname || ''],
            username: [this.username || ''],
            password: [this.password || ''],
        });
    }
}

import { FormBuilder, FormGroup, Validators } from '@angular/forms';

import { ConditioningSession } from './ConditioningSession';

export class ConditioningRecord {
	_id: string;
	userId: string;
	sessionId: string;
	date: string;
	duration: number;
	notes: string;
	completed: boolean;
    caloriesBurned: number;

	constructor(record?: Partial<ConditioningRecord> | null) {
		this._id = record?._id || '';
		this.userId = record?.userId || '';
		this.sessionId = record?.sessionId || '';
		this.date = record?.date || '';
		this.duration = record?.duration ?? 0;
		this.notes = record?.notes || '';
		this.completed = record?.completed ?? false;
        this.caloriesBurned = record?.caloriesBurned ?? 0;
	}

	static createFormGroup(
		fb: FormBuilder,
		record?: ConditioningRecord,
		session?: ConditioningSession
	): FormGroup {
		return fb.group({
			sessionId: [record?.sessionId || session?._id || '', Validators.required],
			date: [record?.date || new Date(), Validators.required],
			duration: [
				record?.duration ?? session?.duration ?? 0,
				[Validators.required, Validators.min(1)]
			],
			notes: [record?.notes || ''],
			completed: [record?.completed ?? false],
            caloriesBurned: [record?.caloriesBurned ?? 0],
			userId: [record?.userId || localStorage.getItem('id')],
		});
	}
}

import { FormBuilder, FormGroup, Validators } from '@angular/forms';

export class ConditioningSession {
	_id: string;
	userId: string;
	name: string;
	description: string;
	duration: number;
	category: string;

	constructor(session?: Partial<ConditioningSession> | null) {
		this._id = session?._id || '';
		this.userId = session?.userId || '';
		this.name = session?.name || '';
		this.description = session?.description || '';
		this.duration = session?.duration ?? 0;
		this.category = session?.category || '';
	}

	static createFormGroup(fb: FormBuilder, session?: ConditioningSession): FormGroup {
		return fb.group({
			name: [session?.name || '', [Validators.required, Validators.minLength(3)]],
			description: [session?.description || ''],
			duration: [session?.duration ?? 0, [Validators.required, Validators.min(1)]],
			category: [session?.category || '', Validators.required],
			userId: [session?.userId || localStorage.getItem('id')]
		});
	}
}

