import { FormBuilder, FormGroup, Validators } from '@angular/forms';

export class Meal {
    _id: string;
	name: string;
	calories: number;
	fat: number;
	protein: number;
	carbs: number;
	description: string;
    category: string;

	constructor(meal?: Partial<Meal> | null) {
        this._id = meal?._id || '';
		this.name = meal?.name || '';
		this.calories = meal?.calories ?? 0;
		this.fat = meal?.fat ?? 0;
		this.protein = meal?.protein ?? 0;
		this.carbs = meal?.carbs ?? 0;
		this.description = meal?.description || '';
        this.category = meal?.category || '';
	}

	static createFormGroup(fb: FormBuilder, meal?: Meal): FormGroup {
		return fb.group({
			name: [meal?.name || '', Validators.required],
			calories: [meal?.calories ?? 0, [Validators.required, Validators.min(0)]],
