import { Component, OnInit } from "@angular/core";
import { DayPlan, WeekPlan } from "../../../week-planner/models/WeekPlan";
import { addDays, format } from "date-fns";

import { WeekPlannerService } from "../../../week-planner/week-planner.service";

@Component({
    selector: "app-summary-widget",
    templateUrl: "./summary-widget.component.html",
    standalone: false
})
export class SummaryWidgetComponent implements OnInit {
    constructor(private weekPlannerService: WeekPlannerService) {}

    private _weekPlan: WeekPlan;

    weekPlanLoading = false;

    get weekPlan(): WeekPlan {
        return this._weekPlan;
    }

    get nexThreeDays(): Array<DayPlan> {
        console.log([this.getWorkoutsForDay(1), this.getWorkoutsForDay(2), this.getWorkoutsForDay(3)])
        return [this.getWorkoutsForDay(1), this.getWorkoutsForDay(2), this.getWorkoutsForDay(3)];
    }

    ngOnInit() {
        this.weekPlanLoading = true;
        this.weekPlannerService.getAllWeekPlans().subscribe((data) => {
            this._weekPlan = new WeekPlan(data);
            this.weekPlanLoading = false;
        });
    }

    dayOfWeek(daysAhead: number): string {
        const today = new Date();
        const tomorrow = addDays(today, daysAhead);
        const dayOfWeek = format(tomorrow, "EEEE");
        return dayOfWeek;
    }

    getWorkoutsForDay(daysAhead: number): DayPlan {
        const dayName = this.dayOfWeek(daysAhead);
        const day = this.weekPlan?.days.find((day) => day.dayName === dayName);
        return day;
    }
}

import { Component, OnInit, ViewChild } from '@angular/core';
import { DayPlan, WeekPlan } from './models/WeekPlan';

import { ConditioningLibraryService } from '../conditioning/conditioning-library/conditioning-library.service';
import { ConditioningSession } from '../conditioning/models/ConditioningSession';
import { SideDrawerComponent } from '../shared/components/side-drawer/side-drawer.component';
import { WeekPlannerService } from './week-planner.service';
import { Workout } from '../strength/models/Workout';
import { WorkoutService } from '../strength/workout-library/workout.service';
import { forkJoin } from 'rxjs';

@Component({
	selector: 'app-week-planner',
	templateUrl: './week-planner.component.html',
	standalone: false,
})
export class WeekPlannerComponent implements OnInit {
	@ViewChild(SideDrawerComponent) drawer: SideDrawerComponent;

	resourcesLoading: boolean = false;

	private _selectedDay: DayPlan | null = null;

	private _weekPlan: WeekPlan;
	private _allWorkouts: Workout[] = [];
	private _allConditioningSessions: ConditioningSession[] = [];

	constructor(
		private weekPlannerService: WeekPlannerService,
		private workoutService: WorkoutService,
		private conditioningLibraryService: ConditioningLibraryService,
	) {}

	get weekPlan(): WeekPlan {
		return this._weekPlan;
	}

	get selectedDay(): DayPlan | null {
		return this._selectedDay;
	}

	get allWorkouts(): Workout[] {
		return this._allWorkouts;
	}

	get allConditioningSessions(): ConditioningSession[] {
		return this._allConditioningSessions;
	}

	ngOnInit() {
		const conditioning$ = this.conditioningLibraryService.getAllConditioningSessions();
		const workouts$ = this.workoutService.getAllWorkouts();

		this.resourcesLoading = true;

		forkJoin({
			conditioningSessions: conditioning$,
			workouts: workouts$,
		}).subscribe({
			next: ({ conditioningSessions, workouts }) => {
				this._allConditioningSessions = conditioningSessions;
				this._allWorkouts = workouts;
				this.resourcesLoading = false;

				this.getWeekPlan();
			},
		});
	}

	getWeekPlan() {
		this.weekPlannerService.getAllWeekPlans().subscribe(weekPlan => {
			if (!weekPlan) {
				this.createWeekPlan();
			} else {
				this._weekPlan = new WeekPlan(weekPlan);
			}
		});
	}

	createWeekPlan() {
		this.resourcesLoading = true;

		this._weekPlan = new WeekPlan();

		this.weekPlannerService.createWeekPlan(this._weekPlan.payload()).subscribe(weekPlan => {
			this._weekPlan = new WeekPlan(weekPlan);
			this.resourcesLoading = false;
		});
	}

	updateWeekPlan() {
		this.resourcesLoading = true;
		this.weekPlannerService.updateWeekPlan(this.weekPlan._id, this._weekPlan.payload()).subscribe(() => {
			this.resourcesLoading = false;
		});
	}

	editDay(day: DayPlan) {
		this._selectedDay = day;
		this.drawer.open();
	}

	addWorkoutToDay(day: string, workout: Workout) {
		this._weekPlan.addWorkout(day, workout);
		this.drawer.close();
	}

	addConditioningToDay(day: string, session: ConditioningSession) {
		this._weekPlan.addConditioning(day, session);
		this.drawer.close();
	}

	removeWorkout(day: string, workout: Workout) {
		this._weekPlan.removeWorkout(day, workout);
	}

	removeConditioning(day: string, session: ConditioningSession) {
		this._weekPlan.removeConditioning(day, session);
	}
}

import { Component, OnInit } from '@angular/core';

import { Workout } from '../models/Workout';
import { WorkoutService } from './workout.service';

@Component({
	selector: 'app-workout-library',
	templateUrl: './workout-library.component.html',
	standalone: false,
})
export class WorkoutLibraryComponent implements OnInit {
	constructor(public workoutService: WorkoutService) {}

	workoutsLoading: boolean = false;
	private _allWorkouts: Workout[] = [];
	editModeEnabled: boolean = false;
	selectedWorkout: Workout | null = null;

	ngOnInit(): void {
		this.getAllWorkouts();
	}

	get allWorkouts(): Array<Workout> {
		return this._allWorkouts;
	}

	getAllWorkouts(): void {
		this.workoutsLoading = true;
		this.workoutService.getAllWorkouts().subscribe((workouts: Array<Workout>) => {
			this.workoutsLoading = false;
			this._allWorkouts = workouts.map(e => new Workout(e));
		});
	}

	deleteWorkout(workout: Workout): void {
		this.workoutsLoading = true;
		this.workoutService.deleteWorkout(workout._id).subscribe(() => {
			this.workoutsLoading = false;
			this.getAllWorkouts();
		});
	}

	openEditMode(workout?: Workout): void {
		this.selectedWorkout = workout ?? null;
		this.editModeEnabled = true;
	}

	closeEditMode(): void {
		this.getAllWorkouts();
		this.editModeEnabled = false;
	}
}

import { Component, OnInit } from '@angular/core';

import { Workout } from '../models/Workout';
import { WorkoutRecord } from '../models/WorkoutRecord';
import { WorkoutRecordService } from './workout-records.service';
import { WorkoutService } from '../workout-library/workout.service';
import { format } from 'date-fns';

@Component({
	selector: 'app-workout-records',
	templateUrl: './workout-records.component.html',
	standalone: false,
})
export class WorkoutRecordsComponent implements OnInit {

    workoutsLoading: boolean = false;
    workoutRecordsLoading: boolean = false;

	private _allWorkoutRecords: WorkoutRecord[] = [];
	private _allWorkouts: Workout[] = [];

	editModeEnabled: boolean = false;
	selectedWorkoutRecord: WorkoutRecord | null = null;

	constructor(public workoutRecordService: WorkoutRecordService, public workoutService: WorkoutService) {}

	ngOnInit(): void {
		this.getAllWorkoutRecords();
		this.getAllWorkouts();
	}

	get allWorkouts(): Array<Workout> {
		return this._allWorkouts;
	}

	get allWorkoutRecords(): Array<WorkoutRecord> {
		return this._allWorkoutRecords;
	}

    get workoutRecordLibraryLoading(): boolean {
        return this.workoutRecordsLoading || this.workoutsLoading;
    }

    formatDate(dateInput: string): string {
	    return format(dateInput, "dd/MM/yyyy");
    }

	openEditMode(workoutRecord?: WorkoutRecord): void {
		this.selectedWorkoutRecord = workoutRecord ?? null;
		this.editModeEnabled = true;
	}

	closeEditMode(): void {
		this.getAllWorkoutRecords();
		this.editModeEnabled = false;
	}

	getWorkoutName(workoutId: string): string {
		const workout = this.allWorkouts.find(w => w._id === workoutId);
		return workout?.name ?? '';
	}

	getAllWorkouts() {
        this.workoutsLoading = true;
		this.workoutService.getAllWorkouts().subscribe(allWorkouts => {
			this._allWorkouts = allWorkouts;
            this.workoutsLoading = false;
		});
	}

    getAllWorkoutRecords(): void {
        this.workoutRecordsLoading = true;
		this.workoutRecordService.getAllWorkoutRecords().subscribe(allWorkoutRecords => {
			this._allWorkoutRecords = allWorkoutRecords;
            this.workoutRecordsLoading = false;
		});
	}

    deleteWorkoutRecord(workoutRecord: WorkoutRecord): void {
        this.workoutRecordsLoading = true;
        this.workoutRecordService.deleteWorkoutRecord(workoutRecord._id).subscribe(() => {
            this.getAllWorkoutRecords();
            this.workoutRecordsLoading = false;
        })
    }
}

